-- Launch dataset: six reviewed requirement records for each market/product pathway.
INSERT OR IGNORE INTO requirements (market_id,product_id,type,title,summary,mandatory,legal_basis,official_url,effective_from,last_verified_at) VALUES
('eu','electronics','market-access','EU economic operator identification','Products covered by harmonised rules must identify the responsible manufacturer and, where applicable, the importer or authorised representative.',1,'EU product harmonisation framework','https://single-market-economy.ec.europa.eu/single-market/goods/building-blocks/market-surveillance_en','2024-01-01','2026-08-15'),
('eu','electronics','labeling','Electronic product traceability marking','Products should carry a type, batch or serial identifier and the economic operator contact details required by applicable legislation.',1,'EU market surveillance framework','https://single-market-economy.ec.europa.eu/single-market/goods/building-blocks/market-surveillance_en','2024-01-01','2026-08-15'),
('eu','electronics','waste','WEEE producer responsibilities','Electrical and electronic equipment producers may need registration, reporting and end-of-life financing in destination member states.',1,'Directive 2012/19/EU','https://environment.ec.europa.eu/topics/waste-and-recycling/waste-electrical-and-electronic-equipment-weee_en','2024-01-01','2026-08-15'),
('eu','electronics','radio','Radio Equipment Directive assessment','Connected products using radio functions must meet safety, electromagnetic compatibility and spectrum-use requirements.',1,'Directive 2014/53/EU','https://single-market-economy.ec.europa.eu/sectors/electrical-and-electronic-engineering-industries-eei/radio-equipment-directive-red_en','2024-01-01','2026-08-15'),
('eu','electronics','documentation','Technical documentation retention','Technical documentation and conformity records must be kept for the period required by the applicable legislation.',1,'EU conformity assessment framework','https://single-market-economy.ec.europa.eu/single-market/ce-marking/manufacturers_en','2024-01-01','2026-08-15'),
('eu','electronics','safety','General Product Safety Regulation check','Consumer electronics not fully covered by sector rules remain subject to the EU general product safety framework.',1,'Regulation (EU) 2023/988','https://eur-lex.europa.eu/eli/reg/2023/988/oj/eng','2024-12-13','2026-08-15'),

('eu','textiles','labeling','Fibre composition declaration','Textile labels must state fibre composition using the prescribed fibre names and percentage rules.',1,'Regulation (EU) No 1007/2011','https://eur-lex.europa.eu/eli/reg/2011/1007/oj/eng','2024-01-01','2026-08-15'),
('eu','textiles','language','Destination-language labeling','Mandatory textile composition information must be available in the official language or languages required by the destination member state.',1,'Regulation (EU) No 1007/2011','https://eur-lex.europa.eu/eli/reg/2011/1007/oj/eng','2024-01-01','2026-08-15'),
('eu','textiles','chemical','REACH restricted substances review','Textile articles must comply with applicable restrictions on substances in articles under REACH.',1,'Regulation (EC) No 1907/2006','https://environment.ec.europa.eu/topics/chemicals/reach-regulation_en','2024-01-01','2026-08-15'),
('eu','textiles','safety','GPSR consumer textile duties','Consumer textile products must meet general safety, traceability and online-offer information duties.',1,'Regulation (EU) 2023/988','https://eur-lex.europa.eu/eli/reg/2023/988/oj/eng','2024-12-13','2026-08-15'),
('eu','textiles','documentation','Supplier evidence for textile claims','Importers should retain supplier declarations and test evidence supporting composition and restricted-substance claims.',1,'EU textile and chemical framework','https://eur-lex.europa.eu/eli/reg/2011/1007/oj/eng','2024-01-01','2026-08-15'),
('eu','textiles','origin','Non-preferential origin review','Origin claims and customs declarations should follow EU non-preferential origin rules.',1,'Union Customs Code','https://taxation-customs.ec.europa.eu/customs-4/international-affairs/origin-goods/non-preferential-origin_en','2024-01-01','2026-08-15'),

('eu','food-contact','documentation','Declaration of compliance check','Materials covered by specific EU measures may require a written declaration of compliance supported by documentation.',1,'Regulation (EU) No 10/2011','https://food.ec.europa.eu/food-safety/chemical-safety/food-contact-materials/legislation_en','2024-01-01','2026-08-15'),
('eu','food-contact','manufacturing','Good manufacturing practice','Food contact materials must be manufactured under documented quality assurance and quality control systems.',1,'Regulation (EC) No 2023/2006','https://food.ec.europa.eu/food-safety/chemical-safety/food-contact-materials/legislation_en','2024-01-01','2026-08-15'),
('eu','food-contact','testing','Overall and specific migration testing','Plastic food contact materials may require migration testing under foreseeable conditions of use.',1,'Regulation (EU) No 10/2011','https://eur-lex.europa.eu/eli/reg/2011/10/oj/eng','2024-01-01','2026-08-15'),
('eu','food-contact','traceability','Food contact material traceability','Business operators must maintain traceability to facilitate control, recall and allocation of responsibility.',1,'Regulation (EC) No 1935/2004','https://food.ec.europa.eu/food-safety/chemical-safety/food-contact-materials_en','2024-01-01','2026-08-15'),
('eu','food-contact','labeling','Food contact use instructions','Where safe use depends on conditions, labeling or instructions should identify appropriate limitations and intended use.',1,'Regulation (EC) No 1935/2004','https://food.ec.europa.eu/food-safety/chemical-safety/food-contact-materials_en','2024-01-01','2026-08-15'),
('eu','food-contact','national-rules','Member-state measure review','Materials without fully harmonised EU rules may remain subject to national measures in the destination country.',1,'EU food contact materials framework','https://food.ec.europa.eu/food-safety/chemical-safety/food-contact-materials/legislation_en','2024-01-01','2026-08-15'),

('us','electronics','radio','FCC supplier conformity records','Applicable unintentional radiators require the correct FCC authorisation route and supporting compliance records.',1,'47 CFR Parts 2 and 15','https://www.fcc.gov/engineering-technology/laboratory-division/general/equipment-authorization','2024-01-01','2026-08-15'),
('us','electronics','safety','CPSC consumer product review','Consumer electronics must be reviewed for applicable CPSC-administered rules, bans and reporting duties.',1,'Consumer Product Safety Act','https://www.cpsc.gov/Business--Manufacturing/Business-Education','2024-01-01','2026-08-15'),
('us','electronics','energy','Federal energy conservation standards','Covered appliances and equipment may be subject to Department of Energy testing, certification and labeling rules.',1,'Energy Policy and Conservation Act','https://www.energy.gov/eere/buildings/appliance-and-equipment-standards-program','2024-01-01','2026-08-15'),
('us','electronics','origin','Country-of-origin marking','Imported articles generally require conspicuous country-of-origin marking unless an exception applies.',1,'19 USC 1304','https://www.cbp.gov/trade/rulings/informed-compliance-publications/marking-country-origin-us-imports','2024-01-01','2026-08-15'),
('us','electronics','chemical','California Proposition 65 screening','Products sold in California should be screened for listed chemical exposures and warning obligations.',1,'California Safe Drinking Water and Toxic Enforcement Act','https://oehha.ca.gov/proposition-65','2024-01-01','2026-08-15'),
('us','electronics','documentation','Importer compliance file','Importers should retain test reports, authorisations, supplier records and product specifications supporting US compliance.',1,'Applicable federal product rules','https://www.cpsc.gov/Business--Manufacturing/Business-Education','2024-01-01','2026-08-15'),

('us','textiles','labeling','Textile fiber content label','Covered textile products must disclose generic fibre names and percentages according to FTC rules.',1,'Textile Fiber Products Identification Act','https://www.ecfr.gov/current/title-16/chapter-I/subchapter-C/part-303','2024-01-01','2026-08-15'),
('us','textiles','labeling','Care instruction label','Manufacturers and importers of covered apparel must attach care instructions that remain legible during the useful life.',1,'FTC Care Labeling Rule','https://www.ftc.gov/business-guidance/resources/clothes-captioning-complying-care-labeling-rule','2024-01-01','2026-08-15'),
('us','textiles','safety','Flammable Fabrics Act review','Apparel, children sleepwear and other covered textile products must meet applicable flammability standards.',1,'Flammable Fabrics Act','https://www.cpsc.gov/Business--Manufacturing/Business-Education/Business-Guidance/Flammable-Fabrics-Act','2024-01-01','2026-08-15'),
('us','textiles','children','Children product certificate','Children textile products subject to CPSC rules may require third-party testing and a Children Product Certificate.',1,'Consumer Product Safety Improvement Act','https://www.cpsc.gov/Business--Manufacturing/Testing-Certification','2024-01-01','2026-08-15'),
('us','textiles','origin','Textile country-of-origin disclosure','Textile labels and import documents must use origin information consistent with US customs and FTC requirements.',1,'19 USC 1304 and FTC rules','https://www.cbp.gov/trade/rulings/informed-compliance-publications/marking-country-origin-us-imports','2024-01-01','2026-08-15'),
('us','textiles','records','Labeling substantiation records','Businesses should retain purchase, composition and supplier records supporting textile label claims.',1,'FTC textile rules','https://www.ecfr.gov/current/title-16/chapter-I/subchapter-C/part-303','2024-01-01','2026-08-15'),

('us','food-contact','safety','FDA food contact substance status','Each substance used in a food contact article must have a lawful basis for its intended use.',1,'Federal Food Drug and Cosmetic Act','https://www.hfpappexternal.fda.gov/scripts/fdcc/index.cfm?set=FCN','2024-01-01','2026-08-15'),
('us','food-contact','notification','Food Contact Notification review','A new food contact substance or use may require an effective Food Contact Notification before marketing.',1,'21 USC 348','https://www.hfpappexternal.fda.gov/scripts/fdcc/index.cfm?set=FCN','2024-01-01','2026-08-15'),
('us','food-contact','manufacturing','Food contact good manufacturing practice','Food contact articles must be produced under conditions that keep migration within lawful and safe limits.',1,'21 CFR 174.5','https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-174','2024-01-01','2026-08-15'),
('us','food-contact','testing','Intended-use migration assessment','Compliance assessment should reflect food type, contact time, temperature and other intended-use conditions.',1,'FDA food contact guidance','https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-174','2024-01-01','2026-08-15'),
('us','food-contact','documentation','Supplier regulatory status letter','Importers should obtain documentation identifying the regulatory basis and limitations for each food contact substance.',1,'FDA food contact framework','https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-174','2024-01-01','2026-08-15'),
('us','food-contact','import','FDA import admissibility review','Imported food contact articles may be examined for compliance with applicable FDA requirements at entry.',1,'Federal Food Drug and Cosmetic Act','https://www.fda.gov/industry/import-program-food-and-drug-administration-fda','2024-01-01','2026-08-15'),

('uk','electronics','certification','Applicable UK conformity assessment','Manufacturers must identify the UK product legislation and use the permitted conformity assessment route.',1,'UK product safety legislation','https://www.gov.uk/guidance/using-the-ukca-marking','2024-01-01','2026-08-15'),
('uk','electronics','restriction','UK RoHS restricted substances','Electrical and electronic equipment placed on the Great Britain market must meet applicable UK RoHS restrictions.',1,'Restriction of Hazardous Substances Regulations 2012','https://www.gov.uk/guidance/rohs-compliance-and-guidance','2024-01-01','2026-08-15'),
('uk','electronics','waste','UK WEEE producer duties','Producers may need registration, reporting and financing arrangements for electrical equipment waste.',1,'Waste Electrical and Electronic Equipment Regulations 2013','https://www.gov.uk/guidance/electrical-and-electronic-equipment-eee-producer-responsibility','2024-01-01','2026-08-15'),
('uk','electronics','radio','UK radio equipment requirements','Radio products must satisfy applicable safety, electromagnetic compatibility and spectrum requirements.',1,'Radio Equipment Regulations 2017','https://www.gov.uk/government/publications/radio-equipment-regulations-2017','2024-01-01','2026-08-15'),
('uk','electronics','importer','UK importer identification','Where required, the UK importer name and postal address must accompany the product or its documentation.',1,'Applicable UK product legislation','https://www.gov.uk/guidance/product-safety-for-businesses-a-to-z-of-industry-guidance','2024-01-01','2026-08-15'),
('uk','electronics','documentation','UK declaration and technical file','The responsible business must prepare and retain the declaration and technical evidence required by the applicable route.',1,'UK conformity assessment framework','https://www.gov.uk/guidance/using-the-ukca-marking','2024-01-01','2026-08-15'),

('uk','textiles','labeling','UK textile fibre composition','Textile products must carry accurate fibre composition information using the prescribed fibre names.',1,'Textile Products Regulations 2012','https://www.businesscompanion.info/en/quick-guides/goods/textile-labelling','2024-01-01','2026-08-15'),
('uk','textiles','safety','General product safety assessment','Consumer textiles should undergo a documented safety assessment before supply in Great Britain.',1,'General Product Safety Regulations 2005','https://www.gov.uk/guidance/product-safety-advice-for-businesses','2024-01-01','2026-08-15'),
('uk','textiles','chemical','UK REACH restriction review','Textile articles placed on the Great Britain market must comply with applicable UK REACH restrictions.',1,'UK REACH','https://www.hse.gov.uk/reach/','2024-01-01','2026-08-15'),
('uk','textiles','children','Children clothing safety review','Children clothing should be checked against applicable flammability, drawstring and general safety requirements.',1,'UK product safety framework','https://www.gov.uk/guidance/product-safety-advice-for-businesses','2024-01-01','2026-08-15'),
('uk','textiles','origin','Customs origin evidence','Importers should maintain origin evidence supporting customs declarations and any preferential tariff claim.',1,'UK customs origin rules','https://www.gov.uk/guidance/check-your-goods-meet-the-rules-of-origin','2024-01-01','2026-08-15'),
('uk','textiles','records','Textile compliance record pack','Businesses should retain composition, supplier, testing and labeling records appropriate to the product risk.',1,'UK textile and safety framework','https://www.businesscompanion.info/en/quick-guides/goods/textile-labelling','2024-01-01','2026-08-15'),

('uk','food-contact','safety','UK food contact material safety','Food contact materials must not transfer constituents at levels that endanger health or unacceptably change food.',1,'Retained Regulation (EC) No 1935/2004','https://www.food.gov.uk/business-guidance/food-contact-materials','2024-01-01','2026-08-15'),
('uk','food-contact','manufacturing','UK food contact GMP','Manufacturing operations should use documented quality assurance and control appropriate to food contact materials.',1,'Retained Regulation (EC) No 2023/2006','https://www.food.gov.uk/business-guidance/food-contact-materials','2024-01-01','2026-08-15'),
('uk','food-contact','documentation','UK declaration of compliance','Specific materials may require a declaration of compliance and supporting evidence for the intended conditions of use.',1,'UK food contact materials legislation','https://www.food.gov.uk/business-guidance/food-contact-materials','2024-01-01','2026-08-15'),
('uk','food-contact','testing','Migration and composition assessment','Testing should reflect the food type, contact time, temperature and repeat-use conditions of the final article.',1,'UK food contact materials framework','https://www.food.gov.uk/business-guidance/food-contact-materials','2024-01-01','2026-08-15'),
('uk','food-contact','traceability','Food contact supply-chain traceability','Operators should be able to identify suppliers and customers for materials and articles at each stage.',1,'Retained Regulation (EC) No 1935/2004','https://www.food.gov.uk/business-guidance/food-contact-materials','2024-01-01','2026-08-15'),
('uk','food-contact','labeling','Safe-use labeling and instructions','Articles not obviously intended for food contact should carry suitable identification and any safe-use limitations.',1,'UK food contact materials legislation','https://www.food.gov.uk/business-guidance/food-contact-materials','2024-01-01','2026-08-15');

